INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "裴坚", "aliases": ["裴堅"], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "吴越丞相。952年九月甲寅朔去世。此前履历和生年未载。", "biography": null, "status": "draft", "id": "c3e0527f-cca1-5261-afe5-8b425472e693"}, {"name": "吴延福", "aliases": ["吳延福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越台州刺史。952年九月裴坚去世后任同参相府事。生卒年未载。", "biography": null, "status": "draft", "id": "451e8e6e-3f61-551c-ba3e-946a9bdf9e3f"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "高谟翰", "aliases": ["高謨翰", "高模翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高谟翰，契丹前锋将领。", "biography": null, "status": "draft", "id": "70516658-fa9a-5bd1-8a0a-55b9844d4772"}, {"name": "何福进", "aliases": ["何福進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：何福进，宿卫军校、力战者。", "biography": null, "status": "draft", "id": "9212470a-66f0-53db-8b65-ab0f833848be"}, {"name": "刘诚诲", "aliases": ["劉誠誨", "刘诲", "劉誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周龙捷都指挥使。952年受成德节度使何福进派遣驻贝州抵御契丹。《旧五代史》同场写刘诲，按同一军职及行动对应，原字保留。生卒年未载。", "biography": null, "status": "draft", "id": "e74fcaa8-5612-5c2a-aa18-94c9789e34c1"}, {"name": "何继筠", "aliases": ["何繼筠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周牙内都指挥使。《旧五代史》记952年九月与刘诲等率兵抵御契丹。生卒年未载。", "biography": null, "status": "draft", "id": "e59a4ca8-0d91-5c2e-9d9c-eb4fd0480c85"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "赵进（后蜀将领）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀奉銮肃卫都虞候。952年率兵向利州，得知后周在关中集兵是为了防备北汉后返回。缺少与已录后唐贝州刺史赵进的连续履历证据，暂分人物。生卒年未载。", "biography": null, "status": "draft", "id": "a1963b46-e1b7-5ffb-b679-a1b548bcb24a"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "欧阳广", "aliases": ["歐陽廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉水人。952年上书警告边镐不适合统帅湖南，建议另择将帅、增兵，未获回复。生卒年未载。", "biography": null, "status": "draft", "id": "61774c0b-0f14-586f-8c16-90636b785ac9"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "何敬真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武陵人，朗州步军指挥使。950年率部族兵攻破韩礼在杨柳桥的防线；马希萼入长沙后任他为朗州牙内都指挥使，率兵戍守。生卒年未载。", "biography": null, "status": "draft", "id": "0ce9ccfa-b68b-575c-96b0-8022528be7ad"}, {"name": "张亻放（楚军指挥使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国诸军指挥使。951年与王逵、周行逢、何敬真共同处理朗州军府事务。电子底本姓名末字写作“亻放”，字形待核，暂不与其他记载中的张仿合并。生卒年未载。", "biography": null, "status": "draft", "id": "b66c1113-4e1b-5c98-9a58-2258c1bad288"}, {"name": "蒲公益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州牙将。952年与王逵等受刘言任命为指挥使。后文同一行动写薄公益，字形对应待同场回查，未据姓字另造人物。生卒年未载。", "biography": null, "status": "draft", "id": "e6f84c28-a623-5591-99b2-53a8d5d9a4e4"}, {"name": "朱全琇", "aliases": ["硃全琇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州牙将。952年与王逵等受刘言任命为指挥使，姓名底本写硃全琇。生卒年未载。", "biography": null, "status": "draft", "id": "88df4471-92c7-542f-b91b-ec31a9110353"}, {"name": "宇文琼", "aliases": ["宇文瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州牙将。952年与王逵等受刘言任命为指挥使。生卒年未载。", "biography": null, "status": "draft", "id": "9a1b03e4-dc67-5673-acc6-4cb0bf387dec"}, {"name": "彭万和", "aliases": ["彭萬和"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州牙将。952年与王逵等受刘言任命为指挥使。生卒年未载。", "biography": null, "status": "draft", "id": "1bf265a7-65f9-5128-9bd7-c12bfd0dbed0"}, {"name": "潘叔嗣", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其果敢，与周行逢、张文表交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "0aa70d0f-a11c-50f9-a0e8-3e0a7278f26d"}, {"name": "张文表", "aliases": ["張文表"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其善战，与周行逢、潘叔嗣交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "2a798366-dcd5-5e9c-a10a-a03e10aaa852"}, {"name": "刘瑫（楚蛮酋）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚地地方首领，任土团都指挥使。952年被任为西境镇遏使，防备苻彦通。原书未明具体族属，不与后周文官刘涛混同，生卒年未载。", "biography": null, "status": "draft", "id": "db1c2c95-b453-50d5-8ca1-a92fd75786e3"}, {"name": "福庆长公主（郭威妹）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郭威的妹妹、李重进的母亲。福庆为封号，原文未给个人名字及生卒年。", "biography": null, "status": "draft", "id": "9351d90a-840f-595e-ad05-5bc4b9300298"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

